int gcd(int a, int b){
    int c;
    while (bool(b)){
        c = b;
        b = a % b;
        a = c;
    }
    return a;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    int x = int(fragCoord.x / 2.0);
    int y = int(fragCoord.y / 2.0);

    fragColor = vec4(gcd(x, y) > 1);
}
